def envelope():return {'source':b.source_ref(b.snapshot(),'cal.definition.implementation'),'scope':b.SCOPE,'role':'candidate-necessary-technical-realization-and-scoped-use-declarations','authority_effect':'none','claim_scope':'necessary-declarations-and-proposed-correspondence-only','facets':{name:'hyp:'+name for name in AXES},'actual_owner_review_ref':'','accepted_map_refs':[]}
def valid_profile(x):return x['before']==x['after']==envelope() and set(x['forbidden'])==set(FORBIDDEN) and not any(x['forbidden'].values()) and x['source_role_preserved'] and x['carrier_and_actual_meanings_separate'] and x['consumer_findings_retained'] and not x['semantic_acceptance_claimed'] and not x['actual_outcome_claimed']
def profiles():
 baseline={'before':envelope(),'after':envelope(),'forbidden':{name:False for name in FORBIDDEN},'source_role_preserved':True,'carrier_and_actual_meanings_separate':True,'consumer_findings_retained':True,'semantic_acceptance_claimed':False,'actual_outcome_claimed':False};rows=[]
 def add(name,mutation,expected):
  x=copy.deepcopy(baseline);mutation(x);assert valid_profile(x)==expected,name;rows.append({'case_id':name,'profile':x,'expected_rejection':not expected,'qualified_hypothesis_satisfied':valid_profile(x),'accepted_semantic_map':False})
 add('exact-unaccepted-Implementation-profile',lambda x:None,True)
 for name in FORBIDDEN:add('reject-'+name,lambda x,name=name:x['forbidden'].update({name:True}),False)
 for name in ['source_role_preserved','carrier_and_actual_meanings_separate','consumer_findings_retained']:add('missing-'+name,lambda x,name=name:x.update({name:False}),False)
 for name in ['semantic_acceptance_claimed','actual_outcome_claimed']:add('unreviewed-'+name,lambda x,name=name:x.update({name:True}),False)
 for name in ['scope','role','authority_effect','claim_scope']:add('changed-'+name,lambda x,name=name:x['after'].update({name:'hyp:changed'}),False)
 return rows
def valid_frame(x):return x['before']==x['after']==envelope() and x['selected'] is True and set(x['map_fields'])==set(MAP_FIELDS) and all(x['map_fields'].values()) and set(x['accepted_map_refs'])==set(MAP_FIELDS) and not any(x['accepted_map_refs'].values()) and x['owner_review_ref']=='' and x['full_alignment_claimed'] is False and x['actual_outcome_claimed'] is False and x['source_role_collapsed'] is False and x['upstream_findings_retained'] is True and x['explicit_sibling_refs']==SIBLINGS
def frames():
 baseline={'before':envelope(),'after':envelope(),'selected':True,'map_fields':{name:'proposed-map-or-explicit-residue' for name in MAP_FIELDS},'accepted_map_refs':{name:'' for name in MAP_FIELDS},'owner_review_ref':'','full_alignment_claimed':False,'actual_outcome_claimed':False,'source_role_collapsed':False,'upstream_findings_retained':True,'explicit_sibling_refs':SIBLINGS};rows=[]
 def add(name,mutation,expected):
  x=copy.deepcopy(baseline);mutation(x);assert valid_frame(x)==expected,name;rows.append({'case_id':name,'frame':x,'expected_rejection':not expected,'qualified_unaccepted_frame_satisfied':valid_frame(x)})
 add('complete-pending-Implementation-map',lambda x:None,True)
 for name in MAP_FIELDS:
  add('missing-'+name,lambda x,name=name:x['map_fields'].pop(name),False);add('empty-'+name,lambda x,name=name:x['map_fields'].update({name:''}),False);add('invented-acceptance-'+name,lambda x,name=name:x['accepted_map_refs'].update({name:'hyp:accepted'}),False)
 for name in ['full_alignment_claimed','actual_outcome_claimed','source_role_collapsed']:add('forbidden-'+name,lambda x,name=name:x.update({name:True}),False)
 add('discarded-findings',lambda x:x.update(upstream_findings_retained=False),False);add('silent-sibling-merge',lambda x:x.update(explicit_sibling_refs=[]),False);add('changed-owner-coordinate',lambda x:x['after']['facets'].update(implementationOwner='hyp:changed'),False)
 return rows
def verify(write=False):
 runtime=v.f.current_bindings();observation=consumer.inspect();terminal=consumer.load(b.UNIT/'carrier-inspection-command-result.json');assert terminal['exit_code']==0 and not(b.UNIT/terminal['stderr']).read_bytes();findings=observation['unresolved_consumer_findings'];assert len(findings)==17 and all(row['status']=='unresolved' and not row['accepted_map_refs'] for row in findings)
 assert observation['source_coordinate_account_complete'] and not observation['accepted_semantic_correspondence_complete'] and not observation['accepted_semantic_map_refs'] and not observation['actual_Implementation_instance_effects_established']
 ps,fs=profiles(),frames();refs=[b.ref(b.UNIT/name) for name in ['verify_authority_profile.py','carrier-consumer-inspection.json','carrier-inspection-command-result.json','CONSUMER-REVIEW.md','types-logic-receipt.json']]+list(observation['selected_inputs'].values());b.unchanged(refs)
 report={'schema_version':'Implementation-qualified-authority-profile/v1-candidate','status':'PASS-for-qualified-unaccepted-Implementation-profiles','authority_effect':'none','source':observation['source'],'profiles':ps,'finite_comparison_frames':fs,'source_map_obligations':MAP_FIELDS,'accepted_source_to_carrier_or_consumer_map_refs':[],'cross_definition_review_findings':findings,'carrier_consumer_observation':observation,'actual_checks':observation['checks'],'actual_check_count':observation['check_count'],'selected_inputs':{str(i):ref for i,ref in enumerate(refs)},'checker_bindings':[b.ref(b.UNIT/name) for name in ['verify_authority_profile.py','inspect_carrier_consumers.py']],'runtime_bindings':runtime,'bound_package_validator_executed':False,'canonical_or_candidate_carrier_writer_executed':False,'native_or_live_consumer_executed':False,'actual_instance_effects_created':False,'direct_carrier_or_consumer_alignment_accepted':False,'new_authorities_or_relations_created':0,'source_fidelity':'pending','semantic_ready':False,'mechanized_proof':False,'claim_ceiling':'Qualified finite hypotheses retain exact source scopes and pending maps; no actual build, deployment, conformance, value, authority, owner acceptance, fidelity or whole proof.'}
 assert runtime==v.f.current_bindings();b.unchanged(refs)
 if write:b.put('authority-profile-checks.json',report)
 else:assert b.r.same_json(report,consumer.load(b.UNIT/'authority-profile-checks.json')),'Fresh authority profiles differ'
 return report
if __name__=='__main__':
 report=verify('--write' in b.sys.argv);print(json.dumps({'result':report['status'],'profiles':len(report['profiles']),'rejected_profiles':sum(row['expected_rejection'] for row in report['profiles']),'frames':len(report['finite_comparison_frames']),'rejected_frames':sum(row['expected_rejection'] for row in report['finite_comparison_frames']),'pending_map_obligations':len(report['source_map_obligations']),'semantic_ready':False},indent=2))
